INSERT INTO public.capability_execution_contracts(capability_slug,endpoint_id,version,status,requires,produces,input_map,fixed_params,output_map,cardinality,identifies,max_fan_out,preconditions,pagination,effect,price_model,freshness_seconds,sample_payload,validated_at,validated_note,notes) SELECT 'procurement.company-name-mentions',e.id,1,'active','[{"fact_type":"company.nl.registered_name","subject_role":"subject","optional":false}]'::jsonb,'[{"fact_type":"tenderned.publication_page","subject_role":"subject","cardinality":"one","optional":false}]'::jsonb,'{"company.nl.registered_name":{"in":"query","name":"search"}}'::jsonb,'{"page":0,"size":20}'::jsonb,'{"base":"$","produces":{"tenderned.publication_page":{"path":"$"}}}'::jsonb,'one',NULL,1,'{}','{}','read','per_call',3600,'{"last":false,"size":10,"first":true,"number":0,"content":[{"link":{"href":"https://www.tenderned.nl/aankondigingen/overzicht/330128","title":"self"},"score":27.810678,"kenmerk":458244,"digitaal":false,"europees":true,"procedure":{"code":"NA"},"tsenderLink":"https://s2c.mercell.com/today/80221","tsenderNaam":"Mercell","publicatieId":"330128","typeOpdracht":{"code":"L","omschrijving":"Leveringen"},"publicatiecode":{"code":"EF04","omschrijving":"Vooraankondiging die alleen ter informatie wordt gebruikt - algemene richtlijn"},"typePublicatie":{"code":"VAK","omschrijving":"Vooraankondiging"},"publicatieDatum":"2024-03-23","aanbestedingNaam":"Marktconsultatie Laadpalen gemeente Nijmegen","publicatiestatus":{"code":"PUB","omschrijving":"Gepubliceerd"},"isEformsWijziging":false,"opdrachtgeverNaam":"gemeente Nijmegen","opdrachtBeschrijving":"Gemeente Nijmegen heeft circa 430 laadpalen in de openbare ruimte staan middels verschillende concessies. Daarnaast hebben we 42 semi publieke laadpalen op eigen terreinen staan. Deze laadpalen hebben we in eigen beheer. Voor vervanging en uitbreiding van de laadpalen op eigen terreinen (parkeergarages, P&R en deelvoertuigen in de openbare ruimte) gaan wij op zoek naar een aanbieder. Wij zoeken hierbij een aanbieder die de laadpalen levert, 2elijns onderhoud doet aan de laadpalen en de benodigde software kan leveren. Wij willen hierbij niet afhankelijk zijn van een CPO, zodat we zelf de controle hebben.","isVroegtijdigeBeeindiging":false},{"link":{"href":"https://www.tenderned.nl/aankondigingen/overzicht/376218","title":"self"},"score":26.835663,"kenmerk":499200,"digitaal":true,"europees":true,"procedure":{"code":"OPE","omschrijving":"Openbaar"},"publicatieId":"376218","typeOpdracht":{"code":"D","omschrijving":"Diensten"},"publicatiecode":{"code":"EF29","omschrijving":"Aankondiging gegunde opdracht - algemene richtlijn, standaardregeling"},"sluitingsDatum":"2025-02-20T10:00:00","typePublicatie":{"code":"AGO","omschrijving":"Aankondiging gegunde opdracht"},"publicatieDatum":"2025-04-24","aanbestedingNaam":"Laadpalen","publicatiestatus":{"code":"PUB","omschrijving":"Gepubliceerd"},"isEformsWijziging":false,"opdrachtgeverNaam":"Hoogheemraadschap van Schieland en de Krimpenerwaard","opdrachtBeschrijving":"HHKS wenst een Raamovereenkomst af te sluiten voor het leveren, installeren, beheren, hosten en onderhouden van nieuw te plaatsen laadinfrastructuur en beheren, hosten en onderhouden van de bestaande laadpalen. Er zijn laadpalen gewenst in verband met de elektrificatie van het wagenpark van HHSK.","isVroegtijdigeBeeindiging":false,"aantalDagenTotSluitingsDatum":-566},{"link":{"href":"https://www.tenderned.nl/aankondigingen/overzicht/361435","title":"self"},"score":26.835663,"kenmerk":499200,"digitaal":true,"europees":true,"procedure":{"code":"OPE","omschrijving":"Openbaar"},"publicatieId":"361435","typeOpdracht":{"code":"D","omschrijving":"Diensten"},"publicatiecode":{"code":"EF16","omschrijving":"Aankondiging van een opdracht - algemene richtlijn, standaardregeling"},"sluitingsDatum":"2025-02-20T10:00:00","typePublicatie":{"code":"AAO","omschrijving":"Aankondiging opdracht"},"publicatieDatum":"2024-12-18","aanbestedingNaam":"Laadpalen","publicatiestatus":{"code":"PUB","omschrijving":"Gepubliceerd"},"isEformsWijziging":false,"opdrachtgeverNaam":"Hoogheemraadschap van Schieland en de Krimpenerwaard","opdrachtBeschrijving":"HHKS wenst een Raamovereenkomst af te sluiten voor het leveren, installeren, beheren, hosten en onderhouden van nieuw te plaatsen laadinfrastructuur en beheren, hosten en onderhouden van de bestaande laadpalen. Er zijn laadpalen gewenst in verband met de elektrificatie van het wagenpark van HHSK.","isVroegtijdigeBeeindiging":false,"aantalDagenTotSluitingsDatum":-566},{"link":{"href":"https://www.tenderned.nl/aankondigingen/overzicht/307391","title":"self"},"score":25.971382,"kenmerk":425833,"digitaal":false,"europees":true,"procedure":{"code":"OPE","omschrijving":"Openbaar"},"tsenderLink":"https://s2c.mercell.com/today/30597","tsenderNaam":"Mercell Source-to-Contract","publicatieId":"307391","typeOpdracht":{"code":"D","omschrijving":"Diensten"},"publicatiecode":{"code":"SF14","omschrijving":"Kennisgeving van aanvullende informatie, informatie over een onvolledige procedure of rectificatie"},"sluitingsDatum":"2023-09-29T09:00:00","typePublicatie":{"code":"REC","omschrijving":"Rectificatie"},"publicatieDatum":"2023-08-15","aanbestedingNaam":"Overname en plaatsing publieke laadinfrastructuur gemeente Utrecht","publicatiestatus":{"code":"PUB","omschrijving":"Gepubliceerd"},"isEformsWijziging":true,"opdrachtgeverNaam":"Gemeente Utrecht","opdrachtBeschrijving":"Het doel van de aanbesteding is een toekomstbestendige laadinfrastructuur voor de elektrisch rijders (bewoners en bezoekers) in Utrecht te verzorgen. Dit gaat om zowel het functionerend houden van de bestaande publieke laadpalen als het plaatsen van nieuwe laadinfrastructuur in lijn met de verwachte behoefte. \nOm dit te realiseren kopen we het beheer, onderhoud en exploitatie van circa 700 bestaande laadpalen, en de plaatsing, beheer, onderhoud en exploitatie van circa 1.000 nieuwe publieke laadpalen in lijn met de verwachte behoefte in.","isVroegtijdigeBeeindiging":false,"aantalDagenTotSluitingsDatum":-1076},{"link":{"href":"https://www.tenderned.nl/aankondigingen/overzicht/307240","title":"self"},"score":25.971382,"kenmerk":425833,"digitaal":false,"europees":true,"procedure":{"code":"OPE","omschrijving":"Openbaar"},"tsenderLink":"https://s2c.mercell.com/today/30597","tsenderNaam":"Mercell Source-to-Contract","publicatieId":"307240","typeOpdracht":{"code":"D","omschrijving":"Diensten"},"publicatiecode":{"code":"SF02","omschrijving":"Aankondiging van een opdracht"},"sluitingsDatum":"2023-09-29T09:00:00","typePublicatie":{"code":"AAO","omschrijving":"Aankondiging opdracht"},"publicatieDatum":"2023-08-13","aanbestedingNaam":"Overname en plaatsing publieke laadinfrastructuur gemeente Utrecht","publicatiestatus":{"code":"PUB","omschrijving":"Gepubliceerd"},"isEformsWijziging":false,"opdrachtgeverNaam":"Gemeente Utrecht","opdrachtBeschrijving":"Het doel van de aanbesteding is een toekomstbestendige laadinfrastructuur voor de elektrisch rijders (bewoners en bezoekers) in Utrecht te verzorgen. Dit gaat om zowel het functionerend houden van de bestaande publieke laadpalen als het plaatsen van nieuwe laadinfrastructuur in lijn met de verwachte behoefte. \nOm dit te realiseren kopen we het beheer, onderhoud en exploitatie van circa 700 bestaande laadpalen, en de plaatsing, beheer, onderhoud en exploitatie van circa 1.000 nieuwe publieke laadpalen in lijn met de verwachte behoefte in.","isVroegtijdigeBeeindiging":false,"aantalDagenTotSluitingsDatum":-1076},{"link":{"href":"https://www.tenderned.nl/aankondigingen/overzicht/296385","title":"self"},"score":25.64547,"kenmerk":410073,"digitaal":false,"europees":true,"procedure":{"code":"NA"},"tsenderLink":"https://s2c.mercell.com/today/36835","tsenderNaam":"Mercell Source-to-Contract","publicatieId":"296385","typeOpdracht":{"code":"W","omschrijving":"Werken"},"publicatiecode":{"code":"SF07","omschrijving":"Erkenningsregeling - speciale sectoren"},"typePublicatie":{"code":"AAO","omschrijving":"Aankondiging opdracht"},"publicatieDatum":"2023-04-27","aanbestedingNaam":"Openbaar bod publieke EV laadpalen","publicatiestatus":{"code":"PUB","omschrijving":"Gepubliceerd"},"isEformsWijziging":false,"opdrachtgeverNaam":"Alliander N.V.","opdrachtBeschrijving":"Middels een openbaar bod Publieke EV laadpalen (open house) kunnen Inschrijvers zich aanmelden om het werkpakket Publieke EV laadpalen in het verzorgingsgebied van Alliander N.V. uit te voeren.","isVroegtijdigeBeeindiging":false},{"link":{"href":"https://www.tenderned.nl/aankondigingen/overzicht/326177","title":"self"},"score":25.529152,"kenmerk":452537,"digitaal":false,"europees":true,"procedure":{"code":"OPE","omschrijving":"Openbaar"},"tsenderLink":"https://s2c.mercell.com/today/41551","tsenderNaam":"Mercell","publicatieId":"326177","typeOpdracht":{"code":"L","omschrijving":"Leveringen"},"publicatiecode":{"code":"EF29","omschrijving":"Aankondiging gegunde opdracht - algemene richtlijn, standaardregeling"},"typePublicatie":{"code":"AGO","omschrijving":"Aankondiging gegunde opdracht"},"publicatieDatum":"2024-02-16","aanbestedingNaam":"Laadinfrastructuur","publicatiestatus":{"code":"PUB","omschrijving":"Gepubliceerd"},"isEformsWijziging":false,"opdrachtgeverNaam":"Politie","opdrachtBeschrijving":"De Opdracht omvat de levering van Laadpalen en het implementeren van een Laadbeheersysteem.","isVroegtijdigeBeeindiging":false},{"link":{"href":"https://www.tenderned.nl/aankondigingen/overzicht/301746","title":"self"},"score":25.529152,"kenmerk":417912,"digitaal":false,"europees":true,"procedure":{"code":"OPE","omschrijving":"Openbaar"},"tsenderLink":"https://s2c.mercell.com/today/41551","tsenderNaam":"Mercell Source-to-Contract","publicatieId":"301746","typeOpdracht":{"code":"L","omschrijving":"Leveringen"},"publicatiecode":{"code":"SF02","omschrijving":"Aankondiging van een opdracht"},"sluitingsDatum":"2023-10-05T12:00:00","typePublicatie":{"code":"AAO","omschrijving":"Aankondiging opdracht"},"publicatieDatum":"2023-06-24","aanbestedingNaam":"Laadinfrastructuur","publicatiestatus":{"code":"PUB","omschrijving":"Gepubliceerd"},"isEformsWijziging":false,"opdrachtgeverNaam":"Politie","opdrachtBeschrijving":"De Opdracht omvat de levering van Laadpalen en het implementeren van een Laadbeheersysteem.","isVroegtijdigeBeeindiging":false,"aantalDagenTotSluitingsDatum":-1070},{"link":{"href":"https://www.tenderned.nl/aankondigingen/overzicht/278739","title":"self"},"score":25.529152,"kenmerk":342557,"digitaal":false,"europees":true,"procedure":{"code":"NOP","omschrijving":"Niet-openbaar"},"tsenderLink":"https://platform.negometrix.com/PublishedTenders.aspx?tenderId=191260","tsenderNaam":"Negometrix3","publicatieId":"278739","typeOpdracht":{"code":"L","omschrijving":"Leveringen"},"publicatiecode":{"code":"SF06","omschrijving":"Aankondiging van een gegunde opdracht - speciale sectoren"},"sluitingsDatum":"2022-02-07T10:00:00","typePublicatie":{"code":"AGO","omschrijving":"Aankondiging gegunde opdracht"},"publicatieDatum":"2022-11-10","aanbestedingNaam":"EV Laadpalen","publicatiestatus":{"code":"PUB","omschrijving":"Gepubliceerd"},"isEformsWijziging":false,"opdrachtgeverNaam":"Schiphol Nederland BV","opdrachtBeschrijving":"Doel van de aanbesteding: de Opdracht\nAangezien Schiphol CO2 reductie doelstellingen wil verwezenlijken de komende jaren, waarbij electrification een centraal thema is, verwachten we de komende jaren flink uit te breiden qua laadfaciliteiten. Daarom is Schiphol voornemens om voor Schiphol en de regionale luchthavens hiervoor middels een aanbesteding tot een tweetal raamovereenkomsten te komen met Gegadigde(n) / Inschrijver(s). Deze raamovereenkomsten zien toe op de levering van verschillende typen AC EV laadpalen. \nAanbestedingsreglement Nutssectoren 2016\nOp deze aanbestedingsprocedure is de  Aanbestedingsreglement Nutssectoren 2016 (ARN2016) van toepassing.\nNegometrix\nDeze aanbesteding zal volledig digitaal via Negometrix geschieden. Voor instructies over het digitaal aanbieden in Negometrix wordt verwezen naar de volgende instructies:\nInstructie Registreren op Negometrix\nInstructie Vraag & Antwoord\nInstructie Digitaal Aanbieden","isVroegtijdigeBeeindiging":false,"aantalDagenTotSluitingsDatum":-1675},{"link":{"href":"https://www.tenderned.nl/aankondigingen/overzicht/248112","title":"self"},"score":25.529152,"kenmerk":342557,"digitaal":false,"europees":true,"procedure":{"code":"NOP","omschrijving":"Niet-openbaar"},"tsenderLink":"https://platform.negometrix.com/PublishedTenders.aspx?tenderId=191260","tsenderNaam":"Negometrix3","publicatieId":"248112","typeOpdracht":{"code":"L","omschrijving":"Leveringen"},"publicatiecode":{"code":"SF02","omschrijving":"Aankondiging van een opdracht"},"sluitingsDatum":"2022-02-07T10:00:00","typePublicatie":{"code":"AAO","omschrijving":"Aankondiging opdracht"},"publicatieDatum":"2021-12-25","aanbestedingNaam":"EV Laadpalen","publicatiestatus":{"code":"PUB","omschrijving":"Gepubliceerd"},"isEformsWijziging":false,"opdrachtgeverNaam":"Schiphol Nederland BV","opdrachtBeschrijving":"Aangezien Schiphol CO2 reductie doelstellingen wil verwezenlijken de komende jaren, waarbij electrification een centraal thema is, verwachten we de komende jaren flink uit te breiden qua laadfaciliteiten. Daarom is Schiphol voornemens om voor Schiphol en de regionale luchthavens hiervoor middels een aanbesteding tot een tweetal raamovereenkomsten te komen met Gegadigde(n) / Inschrijver(s). Deze raamovereenkomsten zien toe op de levering van verschillende typen AC EV laadpalen. \nAanbestedingsreglement Nutssectoren 2016\nOp deze aanbestedingsprocedure is de  Aanbestedingsreglement Nutssectoren 2016 (ARN2016) van toepassing.\nNegometrix\nDeze aanbesteding zal volledig digitaal via Negometrix geschieden. Voor instructies over het digitaal aanbieden in Negometrix wordt verwezen naar de volgende instructies:\nInstructie Registreren op Negometrix\nInstructie Vraag & Antwoord\nInstructie Digitaal Aanbieden\n ","isVroegtijdigeBeeindiging":false,"aantalDagenTotSluitingsDatum":-1675}],"totalPages":23,"totalElements":221,"numberOfElements":10}'::jsonb,now(),'Identity-preserving source fixtures and dependency resolver tests','dutch-identifier-links-v1' FROM public.api_endpoints e JOIN public.apis a ON a.id=e.api_id WHERE a.slug='tenderned' AND e.path='/v2/publicaties' AND e.method='GET';
INSERT INTO public.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('procurement.rsin-mentions','Search TenderNed publication text using the RSIN. Candidate mentions only: not proof of a supplier award, legal-entity match or subsidy receipt.','Search TenderNed publication text using the RSIN. Candidate mentions only: not proof of a supplier award, legal-entity match or subsidy receipt.','government','{"type":"object"}','{"type":"object"}','active') ON CONFLICT(slug) DO NOTHING;
INSERT INTO public.capability_execution_contracts(capability_slug,endpoint_id,version,status,requires,produces,input_map,fixed_params,output_map,cardinality,identifies,max_fan_out,preconditions,pagination,effect,price_model,freshness_seconds,sample_payload,validated_at,validated_note,notes) SELECT 'procurement.rsin-mentions',e.id,1,'active','[{"fact_type":"company.nl.rsin","subject_role":"subject","optional":false}]'::jsonb,'[{"fact_type":"tenderned.publication_page","subject_role":"subject","cardinality":"one","optional":false}]'::jsonb,'{"company.nl.rsin":{"in":"query","name":"search"}}'::jsonb,'{"page":0,"size":20}'::jsonb,'{"base":"$","produces":{"tenderned.publication_page":{"path":"$"}}}'::jsonb,'one',NULL,1,'{}','{}','read','per_call',3600,'{"last":false,"size":10,"first":true,"number":0,"content":[{"link":{"href":"https://www.tenderned.nl/aankondigingen/overzicht/330128","title":"self"},"score":27.810678,"kenmerk":458244,"digitaal":false,"europees":true,"procedure":{"code":"NA"},"tsenderLink":"https://s2c.mercell.com/today/80221","tsenderNaam":"Mercell","publicatieId":"330128","typeOpdracht":{"code":"L","omschrijving":"Leveringen"},"publicatiecode":{"code":"EF04","omschrijving":"Vooraankondiging die alleen ter informatie wordt gebruikt - algemene richtlijn"},"typePublicatie":{"code":"VAK","omschrijving":"Vooraankondiging"},"publicatieDatum":"2024-03-23","aanbestedingNaam":"Marktconsultatie Laadpalen gemeente Nijmegen","publicatiestatus":{"code":"PUB","omschrijving":"Gepubliceerd"},"isEformsWijziging":false,"opdrachtgeverNaam":"gemeente Nijmegen","opdrachtBeschrijving":"Gemeente Nijmegen heeft circa 430 laadpalen in de openbare ruimte staan middels verschillende concessies. Daarnaast hebben we 42 semi publieke laadpalen op eigen terreinen staan. Deze laadpalen hebben we in eigen beheer. Voor vervanging en uitbreiding van de laadpalen op eigen terreinen (parkeergarages, P&R en deelvoertuigen in de openbare ruimte) gaan wij op zoek naar een aanbieder. Wij zoeken hierbij een aanbieder die de laadpalen levert, 2elijns onderhoud doet aan de laadpalen en de benodigde software kan leveren. Wij willen hierbij niet afhankelijk zijn van een CPO, zodat we zelf de controle hebben.","isVroegtijdigeBeeindiging":false},{"link":{"href":"https://www.tenderned.nl/aankondigingen/overzicht/376218","title":"self"},"score":26.835663,"kenmerk":499200,"digitaal":true,"europees":true,"procedure":{"code":"OPE","omschrijving":"Openbaar"},"publicatieId":"376218","typeOpdracht":{"code":"D","omschrijving":"Diensten"},"publicatiecode":{"code":"EF29","omschrijving":"Aankondiging gegunde opdracht - algemene richtlijn, standaardregeling"},"sluitingsDatum":"2025-02-20T10:00:00","typePublicatie":{"code":"AGO","omschrijving":"Aankondiging gegunde opdracht"},"publicatieDatum":"2025-04-24","aanbestedingNaam":"Laadpalen","publicatiestatus":{"code":"PUB","omschrijving":"Gepubliceerd"},"isEformsWijziging":false,"opdrachtgeverNaam":"Hoogheemraadschap van Schieland en de Krimpenerwaard","opdrachtBeschrijving":"HHKS wenst een Raamovereenkomst af te sluiten voor het leveren, installeren, beheren, hosten en onderhouden van nieuw te plaatsen laadinfrastructuur en beheren, hosten en onderhouden van de bestaande laadpalen. Er zijn laadpalen gewenst in verband met de elektrificatie van het wagenpark van HHSK.","isVroegtijdigeBeeindiging":false,"aantalDagenTotSluitingsDatum":-566},{"link":{"href":"https://www.tenderned.nl/aankondigingen/overzicht/361435","title":"self"},"score":26.835663,"kenmerk":499200,"digitaal":true,"europees":true,"procedure":{"code":"OPE","omschrijving":"Openbaar"},"publicatieId":"361435","typeOpdracht":{"code":"D","omschrijving":"Diensten"},"publicatiecode":{"code":"EF16","omschrijving":"Aankondiging van een opdracht - algemene richtlijn, standaardregeling"},"sluitingsDatum":"2025-02-20T10:00:00","typePublicatie":{"code":"AAO","omschrijving":"Aankondiging opdracht"},"publicatieDatum":"2024-12-18","aanbestedingNaam":"Laadpalen","publicatiestatus":{"code":"PUB","omschrijving":"Gepubliceerd"},"isEformsWijziging":false,"opdrachtgeverNaam":"Hoogheemraadschap van Schieland en de Krimpenerwaard","opdrachtBeschrijving":"HHKS wenst een Raamovereenkomst af te sluiten voor het leveren, installeren, beheren, hosten en onderhouden van nieuw te plaatsen laadinfrastructuur en beheren, hosten en onderhouden van de bestaande laadpalen. Er zijn laadpalen gewenst in verband met de elektrificatie van het wagenpark van HHSK.","isVroegtijdigeBeeindiging":false,"aantalDagenTotSluitingsDatum":-566},{"link":{"href":"https://www.tenderned.nl/aankondigingen/overzicht/307391","title":"self"},"score":25.971382,"kenmerk":425833,"digitaal":false,"europees":true,"procedure":{"code":"OPE","omschrijving":"Openbaar"},"tsenderLink":"https://s2c.mercell.com/today/30597","tsenderNaam":"Mercell Source-to-Contract","publicatieId":"307391","typeOpdracht":{"code":"D","omschrijving":"Diensten"},"publicatiecode":{"code":"SF14","omschrijving":"Kennisgeving van aanvullende informatie, informatie over een onvolledige procedure of rectificatie"},"sluitingsDatum":"2023-09-29T09:00:00","typePublicatie":{"code":"REC","omschrijving":"Rectificatie"},"publicatieDatum":"2023-08-15","aanbestedingNaam":"Overname en plaatsing publieke laadinfrastructuur gemeente Utrecht","publicatiestatus":{"code":"PUB","omschrijving":"Gepubliceerd"},"isEformsWijziging":true,"opdrachtgeverNaam":"Gemeente Utrecht","opdrachtBeschrijving":"Het doel van de aanbesteding is een toekomstbestendige laadinfrastructuur voor de elektrisch rijders (bewoners en bezoekers) in Utrecht te verzorgen. Dit gaat om zowel het functionerend houden van de bestaande publieke laadpalen als het plaatsen van nieuwe laadinfrastructuur in lijn met de verwachte behoefte. \nOm dit te realiseren kopen we het beheer, onderhoud en exploitatie van circa 700 bestaande laadpalen, en de plaatsing, beheer, onderhoud en exploitatie van circa 1.000 nieuwe publieke laadpalen in lijn met de verwachte behoefte in.","isVroegt