INSERT INTO public.fact_types(slug,name,description,subject_kind,jurisdiction,value_schema,status,freshness_seconds) VALUES('procurement.ted.identifier_page','procurement.ted.identifier_page','TED notice page matching an exact numeric buyer/winner identifier. Scheme and legal-entity identity unconfirmed; not subsidy receipts.','dataset','NL','{"type":"object","required":["items","coverage","requested_identifier"],"properties":{"items":{"type":"array","items":{"type":"object"}},"coverage":{"type":"object"},"requested_identifier":{"type":"string"}}}'::jsonb,'active',3600) ON CONFLICT(slug) DO NOTHING;
INSERT INTO public.apis(owner_id,slug,name,status,description,long_description,category,docs_url,website_url,origin_url,endpoint_url,authentication_info,is_verified,active,discoverable,listing_type,listing_metadata,integration_mode,settlement_mode,is_external,is_platform_owned,is_community,source,requires_payout_wallet) VALUES(owner,'ted','TED European Procurement Notices','inactive','Search TED notices by exact numeric KVK/RSIN in buyer or winner identifier fields. Identifier scheme and legal-entity identity require confirmation. Includes historical notices; no subsidy or current revenue inference.','Search TED notices by exact numeric KVK/RSIN in buyer or winner identifier fields. Identifier scheme and legal-entity identity require confirmation. Includes historical notices; no subsidy or current revenue inference.','government','https://docs.ted.europa.eu/api/latest/search.html','https://ted.europa.eu','https://api.ted.europa.eu','https://api.ted.europa.eu','{"type":"none"}',false,false,false,'api','{"adapter":"dutch-identifier-links-v1","tags":["TED","EU procurement","KVK","RSIN"],"billing":{"mode":"apiosk_balance"},"coverage_notice":"Search TED notices by exact numeric KVK/RSIN in buyer or winner identifier fields. Identifier scheme and legal-entity identity require confirmation. Includes historical notices; no subsidy or current revenue inference.","auth_headers":[{"name":"Accept","value":"application/json"}],"license":{"name":"TED legal notice and reuse terms","url":"https://ted.europa.eu/en/legal-notice","cost_upstream":"EUR 0.00"}}'::jsonb,'gateway','apiosk_revenue',false,true,false,'manual',false) RETURNING id INTO ted_source_id;
