-- Reviewed identifier graph. Apply only after link adapters are deployed and verified.

BEGIN;

SELECT pg_advisory_xact_lock(hashtext('dutch-identifier-links-v1')); 

DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_types WHERE slug='company.nl.registered_name' AND value_schema='{"type":"string","minLength":1,"maxLength":500}'::jsonb AND status='active') THEN RAISE EXCEPTION 'Conflicting identifier fact: %','company.nl.registered_name'; END IF; END $guard$;

DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_types WHERE slug='company.nl.rsin' AND value_schema='{"type":"string","pattern":"^[0-9]{9}$"}'::jsonb AND status='active') THEN RAISE EXCEPTION 'Conflicting identifier fact: %','company.nl.rsin'; END IF; END $guard$;

DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_types WHERE slug='company.nl.main_establishment_addresses' AND value_schema='{"type":"array","items":{"type":"object"}}'::jsonb AND status='active') THEN RAISE EXCEPTION 'Conflicting identifier fact: %','company.nl.main_establishment_addresses'; END IF; END $guard$;

DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_types WHERE slug='company.nl.main_establishment_id' AND value_schema='{"type":"string","pattern":"^[0-9]{12}$"}'::jsonb AND status='active') THEN RAISE EXCEPTION 'Conflicting identifier fact: %','company.nl.main_establishment_id'; END IF; END $guard$;

