DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_types WHERE slug='location.address_label' AND value_schema='{"type":"string","minLength":1,"maxLength":500}'::jsonb AND status='active') THEN RAISE EXCEPTION 'Conflicting identifier fact: %','location.address_label'; END IF; END $guard$;

DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_types WHERE slug='location.municipality_code' AND value_schema='{"type":"string","pattern":"^[0-9]{4}$"}'::jsonb AND status='active') THEN RAISE EXCEPTION 'Conflicting identifier fact: %','location.municipality_code'; END IF; END $guard$;

DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_types WHERE slug='location.municipality' AND value_schema='{"type":"string","minLength":1,"maxLength":500}'::jsonb AND status='active') THEN RAISE EXCEPTION 'Conflicting identifier fact: %','location.municipality'; END IF; END $guard$;

DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_types WHERE slug='location.neighbourhood_code' AND value_schema='{"type":"string","pattern":"^BU[A-Za-z0-9]{8}$"}'::jsonb AND status='active') THEN RAISE EXCEPTION 'Conflicting identifier fact: %','location.neighbourhood_code'; END IF; END $guard$;

DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_types WHERE slug='location.neighbourhood' AND value_schema='{"type":"string","minLength":1,"maxLength":500}'::jsonb AND status='active') THEN RAISE EXCEPTION 'Conflicting identifier fact: %','location.neighbourhood'; END IF; END $guard$;

DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_types WHERE slug='location.district_code' AND value_schema='{"type":"string","minLength":1,"maxLength":500}'::jsonb AND status='active') THEN RAISE EXCEPTION 'Conflicting identifier fact: %','location.district_code'; END IF; END $guard$;

DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_types WHERE slug='location.parcel_designations' AND value_schema='{"type":"array","items":{"type":"string"}}'::jsonb AND status='active') THEN RAISE EXCEPTION 'Conflicting identifier fact: %','location.parcel_designations'; END IF; END $guard$;

DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_types WHERE slug='location.apartment_right_designations' AND value_schema='{"type":"array","items":{"type":"string"}}'::jsonb AND status='active') THEN RAISE EXCEPTION 'Conflicting identifier fact: %','location.apartment_right_designations'; END IF; END $guard$;

DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_types WHERE slug='location.bag_unit_record' AND value_schema='{"type":"object"}'::jsonb AND status='active') THEN RAISE EXCEPTION 'Conflicting identifier fact: %','location.bag_unit_record'; END IF; END $guard$;

DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_types WHERE slug='location.single_building_href' AND value_schema='{"type":"string","pattern":"^https://api\\.pdok\\.nl/kadaster/bag/ogc/v2/collections/pand/items/[0-9a-f-]{36}$"}'::jsonb AND status='active') THEN RAISE EXCEPTION 'Conflicting identifier fact: %','location.single_building_href'; END IF; END $guard$;

DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_types WHERE slug='location.building_record' AND value_schema='{"type":"object"}'::jsonb AND status='active') THEN RAISE EXCEPTION 'Conflicting identifier fact: %','location.building_record'; END IF; END $guard$;

DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_types WHERE slug='location.cbs_neighbourhood_2025' AND value_schema='{"type":"object"}'::jsonb AND status='active') THEN RAISE EXCEPTION 'Conflicting identifier fact: %','location.cbs_neighbourhood_2025'; END IF; END $guard$;

DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fact_types WHERE slug='location.parcel_records' AND value_schema='{"type":"array","items":{"type":"object"}}'::jsonb AND status='active') THEN RAISE EXCEPTION 'Conflicting identifier fact: %','location.parcel_records'; END IF; END $guard$;

DO $upgrade$ DECLARE previous uuid; BEGIN SELECT c.id INTO STRICT previous FROM public.capability_execution_contracts c JOIN public.api_endpoints e ON e.id=c.endpoint_id JOIN public.apis a ON a.id=e.api_id WHERE a.slug='kvk-dutch-business-register' AND e.path='/api/v1/basisprofielen' AND c.capability_slug='company.registry-profile' AND c.status='active' AND c.version=6 AND c.output_map='{"base":"$","produces":{"company.name":{"path":"$.statutaireNaam"},"company.profile":{"fields":{"sbi_codes":{"path":"$.sbiActiviteiten[*].sbiCode","collect":true},"legal_name":{"path":"$.statutaireNaam"},"trade_names":{"path":"$.handelsnamen[*].naam","collect":true}}},"company_registry.kvknummer":{"path":"$.kvkNummer"}}}'::jsonb FOR UPDATE OF c;
UPDATE public.capability_execution_contracts SET status='retired' WHERE id=previous;

DO $upgrade$ DECLARE previous uuid; BEGIN SELECT c.id INTO STRICT previous FROM public.capability_execution_contracts c JOIN public.api_endpoints e ON e.id=c.endpoint_id JOIN public.apis a ON a.id=e.api_id WHERE a.slug='kvk-dutch-business-register' AND e.path='/api/v1/basisprofielen' AND c.capability_slug='company_registry.lookup' AND c.status='active' AND c.version=6 AND c.output_map='{"base":"$","produces":{"company.name":{"path":"$.statutaireNaam"},"company.profile":{"fields":{"sbi_codes":{"path":"$.sbiActiviteiten[*].sbiCode","collect":true},"legal_name":{"path":"$.statutaireNaam"},"trade_names":{"path":"$.handelsnamen[*].naam","collect":true}}},"company_registry.kvknummer":{"path":"$.kvkNummer"}}}'::jsonb FOR UPDATE OF c;
UPDATE public.capability_execution_contracts SET status='retired' WHERE id=previous;

DO $endpoint$ DECLARE source uuid; BEGIN SELECT id INTO STRICT source FROM public.apis WHERE slug='pdok' AND active AND is_verified AND origin_url='https://api.pdok.nl';
IF EXISTS(SELECT 1 FROM public.api_endpoints WHERE api_id=source AND path='/apiosk/company-address' AND method='GET') THEN RAISE EXCEPTION 'Identifier link endpoint already exists: %','/apiosk/company-address'; END IF;


DO $endpoint$ DECLARE source uuid; BEGIN SELECT id INTO STRICT source FROM public.apis WHERE slug='pdok' AND active AND is_verified AND origin_url='https://api.pdok.nl';
IF EXISTS(SELECT 1 FROM public.api_endpoints WHERE api_id=source AND path='/apiosk/bag-address' AND method='GET') THEN RAISE EXCEPTION 'Identifier link endpoint already exists: %','/apiosk/bag-address'; END IF;


DO $endpoint$ DECLARE source uuid; BEGIN SELECT id INTO STRICT source FROM public.apis WHERE slug='pdok' AND active AND is_verified AND origin_url='https://api.pdok.nl';
IF EXISTS(SELECT 1 FROM public.api_endpoints WHERE api_id=source AND path='/apiosk/bag-unit' AND method='GET') THEN RAISE EXCEPTION 'Identifier link endpoint already exists: %','/apiosk/bag-unit'; END IF;


DO $endpoint$ DECLARE source uuid; BEGIN SELECT id INTO STRICT source FROM public.apis WHERE slug='pdok' AND active AND is_verified AND origin_url='https://api.pdok.nl';
IF EXISTS(SELECT 1 FROM public.api_endpoints WHERE api_id=source AND path='/apiosk/building' AND method='GET') THEN RAISE EXCEPTION 'Identifier link endpoint already exists: %','/apiosk/building'; END IF;


DO $endpoint$ DECLARE source uuid; BEGIN SELECT id INTO STRICT source FROM public.apis WHERE slug='pdok' AND active AND is_verified AND origin_url='https://api.pdok.nl';
IF EXISTS(SELECT 1 FROM public.api_endpoints WHERE api_id=source AND path='/apiosk/neighbourhood' AND method='GET') THEN RAISE EXCEPTION 'Identifier link endpoint already exists: %','/apiosk/neighbourhood'; END IF;


DO $endpoint$ DECLARE source uuid; BEGIN SELECT id INTO STRICT source FROM public.apis WHERE slug='pdok' AND active AND is_verified AND origin_url='https://api.pdok.nl';
IF EXISTS(SELECT 1 FROM public.api_endpoints WHERE api_id=source AND path='/apiosk/linked-parcels' AND method='GET') THEN RAISE EXCEPTION 'Identifier link endpoint already exists: %','/apiosk/linked-parcels'; END IF;





DO $ted$ DECLARE owner uuid; ted_source_id uuid; BEGIN
IF EXISTS(SELECT 1 FROM public.apis WHERE slug='ted') THEN RAISE EXCEPTION 'TED source already exists'; END IF;
SELECT owner_id INTO STRICT owner FROM public.apis WHERE slug='data-overheid-nl' AND is_platform_owned AND settlement_mode='apiosk_revenue';
PERFORM set_config('apiosk.api_review_approved_id',ted_source_id::text,true);
UPDATE public.apis SET status='active',active=true,is_verified=true,discoverable=true,verified_at=now(),approved_at=now(),listing_metadata=listing_metadata||'{"catalog_state":"published"}'::jsonb WHERE id=ted_source_id;
PERFORM set_config('apiosk.api_review_approved_id','',true);END $ted$;



COMMIT;
